-- Aula 03 · Data Collection and Storage · 24/10/2026 · APIs REST, scraping e ingestão no MinIO, com retomada da Aula 02.
-- Usa as tabelas/RPCs existentes no Supabase do aulas_senac. Não execute o schema destrutivo.
-- Reexecução preserva IDs; recusa alterar sala iniciada ou com participantes.
-- O token do professor entra pelo marcador __QUIZ_HOST_TOKEN__, que scripts/quiz_db.mjs troca pelo DCS_HOST_TOKEN do .env.
begin;
select pg_advisory_xact_lock(hashtext('mack-dcs-a03-2026-2'));
do $$ begin if exists (select 1 from quiz_sessions where slug='mack-dcs-a03-2026-2' and (estado <> 'lobby' or pergunta_atual <> 0)) or exists (select 1 from quiz_players where session_slug='mack-dcs-a03-2026-2') then raise exception 'Sala já iniciada ou com participantes: seed cancelado para preservar a rodada.'; end if; end $$;
insert into quiz_sessions (slug,titulo,periodo) values ('mack-dcs-a03-2026-2','Aula 03 — Quiz: APIs, scraping e MinIO','2026-2') on conflict (slug) do update set titulo=excluded.titulo;
with novas as (
  insert into quiz_questions (session_slug,ordem,enunciado,alternativas,segundos,tema,secao,peso) values
  ('mack-dcs-a03-2026-2', 1, 'Na Aula 02, gravar um documento de 992 B levou 0,48 ms em arquivo local e 3,97 ms no MinIO. Mesmo assim, a camada raw foi para o object storage. Qual característica pesou a favor dele?', '["Grava e lê cada documento mais rápido que o disco, porque o acesso é feito por HTTP.", "Permite atualizar só os bytes alterados de um objeto que já foi gravado antes no bucket.", "Traz metadados por objeto, versionamento, ciclo de vida e leitura por qualquer motor S3.", "Organiza os dados em diretórios reais, com travas entre escritores concorrentes."]'::jsonb, 90, 'Tipos de storage e object storage', 'Aula 02 — seções 3.9 e 5.2: latência medida e file contra object storage', 1),
  ('mack-dcs-a03-2026-2', 2, 'A Aula 02 gravou os lotes em telemetria/data=2026-10-17/hora=12/caminhao=CAM-0412/lote_1200.txt, no estilo Hive. O que essa convenção muda quando alguém lê uma única hora da frota?', '["A listagem pelo prefixo da hora traz só os 80 lotes dela, numa página, sem varrer o bucket.", "O MinIO cria diretórios físicos por data, e isso acelera a gravação de cada objeto novo.", "O bucket passa a validar o esquema do JSON antes de aceitar o PUT enviado pelo coletor.", "A partição junta os objetos do mesmo dia num único arquivo comprimido dentro do volume do MinIO."]'::jsonb, 90, 'Chaves e particionamento na camada raw', 'Aula 02 — seções 4.2 e 6.1: listagem por prefixo e chave no estilo Hive', 1),
  ('mack-dcs-a03-2026-2', 3, 'Em março, o provedor da telemetria acrescenta um campo novo no fim de cada linha do TXT. Numa camada raw em schema on read, o que acontece com esse campo?', '["É rejeitado na gravação até que o parser seja atualizado e implantado outra vez.", "Fica guardado no arquivo como chegou e pode ser extraído quando o parser mudar.", "É descartado pelo MinIO, que só aceita linhas com o mesmo número de colunas.", "Exige migrar a tabela de destino antes que o lote seguinte possa ser gravado."]'::jsonb, 90, 'Data lake e schema on read', 'Aula 02 — seção 5.6: schema on write e schema on read', 1),
  ('mack-dcs-a03-2026-2', 4, 'O coletor recebe 429 Too Many Requests com o cabeçalho Retry-After: 30. Qual comportamento segue a regra de retry da aula?', '["Repetir na hora, já que o 429 é transitório e a fonte continua respondendo normalmente.", "Desistir da URL e registrar a falha no manifesto, como se faz com qualquer outro erro 4xx.", "Abrir conexões em paralelo para recuperar, depois da espera, o tempo que se perdeu.", "Esperar os 30 segundos pedidos pelo servidor e repetir, dentro do limite de tentativas."]'::jsonb, 90, 'Status HTTP e rate limit', 'Aula 03 — seções 3.2 e 4.2: códigos de status, 429 e Retry-After', 1),
  ('mack-dcs-a03-2026-2', 5, 'Cem coletores recebem 503 no mesmo instante e repetem quatro vezes com backoff exponencial de base 1 s. Na simulação do Exemplo numérico 1, o que o full jitter muda?', '["Nada no pico: a latência da rede já espalha as repetições, e o jitter só reduz a espera total.", "Dispensa o limite de tentativas, porque as esperas sorteadas nunca coincidem entre clientes.", "Sem jitter, as 100 repetições chegam juntas em 1, 3, 7 e 15 s; com ele, o pico cai a 23 em 100 ms.", "Faz o servidor atender primeiro quem esperou mais, já que as repetições entram numa fila ordenada por chegada."]'::jsonb, 90, 'Retry, backoff e jitter', 'Aula 03 — seções 4.3 e 4.5: backoff com jitter e Exemplo numérico 1', 1),
  ('mack-dcs-a03-2026-2', 6, 'O coletor chama CotacaoMoedaDia com a data 2026-10-15, em formato ISO, e recebe 200 com a lista value vazia. O que essa resposta exige do coletor?', '["Tratar como sucesso, já que o status 200 confirma que a consulta foi aceita como válida.", "Validar o formato MM-DD-AAAA antes da chamada e alertar quando um dia útil vier vazio.", "Repetir com backoff até a API devolver cotações, porque a lista vazia é passageira.", "Trocar a API pelo scraping da página do Banco Central, que mostra a mesma cotação."]'::jsonb, 90, 'PTAX: contrato e realidade', 'Aula 03 — seção 5.3: o que a documentação da PTAX não conta', 1),
  ('mack-dcs-a03-2026-2', 7, 'A consulta CotacaoMoedaPeriodo de GBP entre 09/10 e 16/10/2026 trouxe 25 boletins de 5 dias, sem 10, 11 e 12/10. Por que o monitor de sábado consulta uma janela de dias?', '["Fim de semana e feriado não têm boletim, e a janela garante o último fechamento publicado.", "A API limita a consulta de um dia a cinco registros, e a janela contorna esse limite.", "A consulta de período nunca devolve 500, e por isso a janela dispensa o tratamento de retry.", "O Banco Central publica as cotações com uma semana de atraso, e a janela compensa a espera."]'::jsonb, 90, 'PTAX: janela de cotação', 'Aula 03 — seção 5.4: Exemplo numérico 2, a janela que atravessa o feriado', 1),
  ('mack-dcs-a03-2026-2', 8, 'O books.toscrape.com responde Content-Type: text/html sem charset, e o preço lido de r.text aparece como Â£47.82. Qual correção resolve o problema na origem?', '["Passar r.content (bytes) ao BeautifulSoup, que lê o meta charset UTF-8 do documento.", "Remover o caractere Â com replace antes de converter o preço do livro para número.", "Gravar no MinIO o texto já corrigido, para que o extrator não precise decodificar nada.", "Trocar o seletor p.price_color por um XPath que ignore o símbolo da libra no preço."]'::jsonb, 90, 'Scraping e codificação', 'Aula 03 — seções 6.2 e 7.1: requests, BeautifulSoup e Exemplo numérico 3', 1),
  ('mack-dcs-a03-2026-2', 9, 'Uma equipe precisa dos preços semanais de gasolina por posto. A ANP publica a série histórica em CSV no portal de dados abertos, e um site de comparação mostra os mesmos preços em HTML. Pela tabela de escolha da fonte, qual caminho seguir?', '["Raspar o site de comparação, porque o HTML mostra os preços já organizados por posto.", "Combinar as duas fontes, raspando o site para conferir cada linha do arquivo oficial.", "Baixar o arquivo oficial da ANP, com menos requisições e menos interpretação de página.", "Nenhum dos dois, porque o preço praticado por um posto é dado pessoal protegido pela LGPD."]'::jsonb, 90, 'Escolha da fonte', 'Aula 03 — seção 9: API, scraping ou nenhum dos dois', 1),
  ('mack-dcs-a03-2026-2', 10, 'No Railway, o proxy devolve 502 depois de um put_object que de fato gravou o objeto, e o coletor repete a gravação. Que desenho torna essa repetição segura no monitor?', '["Chave com o horário em milissegundos, para que cada tentativa grave um objeto diferente.", "Extração na mesma execução, gravando só o JSON Lines e descartando o HTML recebido.", "Gravações em paralelo, para que o retry termine antes que o proxy devolva outro 502.", "Chave determinística por fonte, data e página: a repetição regrava os mesmos bytes."]'::jsonb, 90, 'Idempotência e chaves no MinIO', 'Aula 03 — seções 4.4, 10.5 e 10.6: idempotência, 502 do Railway e Exemplo numérico 5', 2)
  on conflict (session_slug,ordem) do update set enunciado=excluded.enunciado, alternativas=excluded.alternativas, segundos=excluded.segundos, tema=excluded.tema, secao=excluded.secao, peso=excluded.peso
  returning id,ordem
)
insert into quiz_answer_key (question_id,correta,explicacao)
select n.id,g.correta,g.explicacao from novas n join (values
  (1, 2, 'A medição da Aula 02 mostrou o objeto mais lento por operação, de 8 a 100 vezes. A escolha veio do padrão de acesso da camada raw: grava uma vez, lê em lote e precisa de procedência. Metadados x-amz-meta-*, versões, ciclo de vida e a API S3 lida por boto3, DuckDB e Spark respondem a esse padrão. O objeto não aceita atualização parcial e a barra da chave não cria diretório.'),
  (2, 0, 'ListObjectsV2 devolve até 1.000 chaves por requisição e filtra por prefixo. Com 20 caminhões e um lote a cada 15 minutos, uma hora tem 80 chaves e cabe numa página, enquanto um ano passa de 700 mil chaves. A partição está no nome da chave: o MinIO não cria pastas, não valida o conteúdo e não junta objetos.'),
  (3, 1, 'Em schema on read, o TXT é gravado como chegou e o esquema é aplicado na leitura. O campo novo fica preservado no objeto bruto e entra no resultado quando o parser for atualizado, reprocessando o original. Rejeitar o campo ou exigir migração antes da gravação descreve schema on write.'),
  (4, 3, 'O 429 indica limite excedido e é transitório. Quando o servidor envia Retry-After, o valor dele prevalece sobre o cálculo do cliente. Repetir na hora mantém a sobrecarga, desistir trata um erro transitório como definitivo, e paralelizar piora o motivo do 429. O limite de tentativas continua valendo.'),
  (5, 2, 'Sem jitter, todos os clientes calculam a mesma espera e voltam juntos em 1, 3, 7 e 15 s, recriando o pico que derrubou o servidor. Na simulação com full jitter (semente fixa), cada espera é sorteada entre 0 e base vezes 2 elevado à tentativa: o pico cai para 23 requisições em 100 ms, e a espera média fica em 7,5 s. O limite de tentativas continua necessário.'),
  (6, 1, 'A PTAX aceita a data em MM-DD-AAAA. Em ISO, a API responde 200 com lista vazia, um erro silencioso que o status não revela. Repetir não muda nada, porque a falha é do cliente. O coletor valida o formato antes de chamar e trata lista vazia em dia útil como alerta no manifesto.'),
  (7, 0, 'Em 16/10/2026, a janela de 8 dias trouxe 5 dias úteis com 5 boletins cada: abertura, três intermediários e fechamento. Sábado, domingo e o feriado de 12/10 não tiveram boletim. A coleta de sábado só encontra o fechamento de sexta numa janela, e a data efetiva da cotação precisa ficar registrada.'),
  (8, 0, 'Sem charset no cabeçalho, o requests assume ISO-8859-1. O símbolo da libra ocupa dois bytes em UTF-8 (C2 A3), que lidos em ISO-8859-1 viram Â£. Com os bytes, o BeautifulSoup lê o meta charset UTF-8 do próprio documento. O MinIO recebe os bytes originais, sem decodificar e recodificar, e um replace esconderia o erro em vez de corrigi-lo.'),
  (9, 2, 'Na tabela da seção 9, a exportação oficial vem antes do scraping: menos requisições, formato estável e nenhuma interpretação de página. Raspar o site de comparação traria a manutenção dos seletores e o risco dos termos de uso. O preço de um posto, que é uma empresa, não é dado pessoal.'),
  (10, 3, 'Com chave derivada da fonte, da data e da página, repetir o PUT grava os mesmos bytes no mesmo objeto e o bucket termina igual. Uma chave com horário criaria uma cópia a cada retry que tivesse chegado, como mostra o Exemplo numérico 5. Descartar o HTML bruto impede reprocessar, e o paralelismo não muda a idempotência.')
) as g(ordem,correta,explicacao) on g.ordem=n.ordem
on conflict (question_id) do update set correta=excluded.correta, explicacao=excluded.explicacao;
insert into quiz_host_tokens (session_slug,token) values ('mack-dcs-a03-2026-2','__QUIZ_HOST_TOKEN__') on conflict (session_slug) do update set token=excluded.token;
do $$ begin if (select count(*) from quiz_questions where session_slug='mack-dcs-a03-2026-2') <> 10 then raise exception 'A sala deve conter exatamente 10 perguntas'; end if; end $$;
commit;
